using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class FinishTrainHudIntegration{
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");Environment.SetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT",null);Application.runInBackground=false;var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var labels=h.Catalog.Select(c=>c.View.GetComponentInChildren<TMP_Text>().text).ToArray();if(labels.Any(t=>t.Contains("검증용")))throw new Exception("Validation wording remains in catalogue");var method=typeof(CanvasWorldHud).GetMethod("Text",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var binding=h.Texts.First(t=>t.View!=null);var lookup=(System.Collections.Generic.Dictionary<string,TMP_Text>)typeof(CanvasWorldHud).GetField("texts",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(h);lookup.Add(binding.Id,binding.View);string previous=binding.View.text;method.Invoke(h,new object[]{binding.Id,"석탄 생성기 · 검증용 · 검증비 철 10"});bool clean=binding.View.text=="석탄 생성기 · 철 10";binding.View.text=previous;lookup.Remove(binding.Id);if(!clean)throw new Exception("Selected label sanitation");var scene=EditorSceneManager.GetActiveScene();if(scene.isDirty)throw new Exception("Unexpected dirty scene");var result=new JObject{{"result","PASS"},{"scene",scene.path},{"sceneDirty",scene.isDirty},{"playMode",EditorApplication.isPlaying},{"runInBackground",Application.runInBackground},{"saveOverrideCleared",Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")==null},{"catalogLabels",new JArray(labels)},{"selectedLabelCleanup",clean},{"researchExperiment",false}};File.WriteAllText("Docs/Measurements/2026-10-02-train-hud-integration/editor-final-state.json",result.ToString());return result.ToString();}}
